/** No remote assets, frameworks, fonts or model calls. */
export function renderWorkspacePage(nonce) {
  if(!/^[A-Za-z0-9+/=]+$/.test(nonce))throw Error('Invalid workspace script nonce');
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>Workkeel · Workspace</title><link rel="stylesheet" href="/workspace.css"></head><body><a class="skip" href="#content">Skip to content</a><div class="shell"><aside><a class="brand" href="?view=overview"><span class="mark" aria-hidden="true">W</span>Workkeel</a><span class="workspace-label" id="workspace-name">Workspace</span><nav aria-label="Main navigation" id="navigation"></nav><div class="sidebar-bottom"><button id="theme" class="quiet">Appearance: system</button><button id="language" class="quiet">繁體中文</button><p class="small">Workspace on this computer</p></div></aside><div class="body"><header><div class="breadcrumb" id="breadcrumb">Workspace / Overview</div><div class="header-actions"><label class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="Search projects and tasks" placeholder="Search projects and tasks"></label><button id="refresh" class="quiet">Refresh</button></div></header><div class="connection" id="connection" role="status" aria-live="polite">Connecting to local workspace…</div><main id="content" tabindex="-1"></main><footer id="footer">Connecting to workspace</footer></div></div><div id="notice" role="status" aria-live="polite"></div><script type="module" nonce="${nonce}" src="/workspace.js"></script></body></html>`;
}

