    'approval-expired':t('Renew task authority','重新確認任務授權'),
    'policy-changed':t('Resolve a policy change','確認政策變更'),
    'evidence-unavailable':t('Restore delivery evidence','恢復交付證據'),
    'awaiting-acceptance':t('Review the delivered result','檢查交付成果'),
    'goal-blocked':t('Delivery needs recovery','交付需要恢復')
