  const controls=['start','pause','resume','recover','cancel'].map(action=>'<button data-goal-action="'+action+'" '+(mayGoal(action,goal)?'':'disabled')+'>'+({start:t('Start delivery service','啟動交付服務'),pause:t('Pause delivery','暫停交付'),resume:t('Resume delivery','恢復交付'),recover:t('Reconcile & recover','核對並恢復'),cancel:t('Request cancellation','要求取消')}[action])+'</button>').join('');
