function commandFeedback(record,action){
  if(record.status!=='confirmed')return t('Request recorded; its outcome needs reconciliation. Do not submit it again with a new key.','已記錄要求，結果仍待核對。請勿使用新的要求識別重送。');
  if(action==='autonomy.cancel')return {'host-confirmed':t('The host confirmed cancellation.','主機已確認取消。'),'cancelled-before-dispatch':t('Cancelled before dispatch.','已在派工前取消。'),'requested-not-confirmed':t('Cancellation requested. The host has not confirmed stopping.','已要求取消，主機尚未確認停止。'),'runtime-already-completed':t('Execution already completed. Acceptance remains separate.','執行已完成，驗收狀態另列。')}[record.result?.cancellation]||t('Cancellation request recorded. Check the host outcome.','已記錄取消要求，請核對主機結果。');
  return t('Host confirmed the request. Reload to inspect effective canonical state.','主機已確認要求。重新載入後核對生效狀態。');
}
function capturePolicyEditor(){
  const form=$('policy-form');if(!form)return null;const data=new FormData(form),settings={};
  for(const name of ['model','reasoning','service']){const mode=data.get(name+'-mode'),value=String(data.get(name+'-value')??'').trim();if(mode==='fixed'&&!value)throw Error(t('A fixed choice requires a value.','指定模式必須填寫值。'));settings[name]={mode,...(mode==='fixed'?{value}:{})};}
  if(!policyEditor)return settings;
  const catalog=hookData.capabilities?.catalog||policyEditor.models,allowed=new Set(data.getAll('allowed-model'));
  if(!allowed.size)throw Error(t('Keep at least one allowed model.','至少保留一個可用模型。'));
  policyEditor.models=catalog.filter(model=>allowed.has(model.id)).map(model=>structuredClone(model));
  if(policyContext==='project')policyEditor.project=settings;
  else {if(!/^[A-Za-z0-9][A-Za-z0-9._-]{0,95}$/.test(policyMatch))throw Error(t('Choose a context identifier before saving a rule.','儲存規則前請填寫情境識別。'));const existing=policyEditor.rules.find(rule=>rule.layer===policyContext&&rule.match===policyMatch);if(existing)existing.settings=settings;else policyEditor.rules.push({id:policyContext+'-'+policyMatch,layer:policyContext,match:policyMatch,settings});}
  const allowedIds=new Set(policyEditor.models.map(model=>model.id));for(const values of [policyEditor.project,...policyEditor.rules.map(rule=>rule.settings)])if(values.model?.mode==='fixed'&&!allowedIds.has(values.model.value))throw Error(t('A fixed model rule uses a disabled model. Re-enable that model or change the rule before saving.','指定模型規則引用了已停用模型。儲存前請重新啟用該模型或調整規則。'));
  policyEditor.version=(hookData.entries?.length??0)+1;return structuredClone(policyEditor);
}
