function analysis(){
  if(!analysisData)return heading(t('Recorded activity','已記錄活動'),t('Explore measured work by activity, tool and reported model.','依活動、工具與回報模型檢查已量測工作。'))+empty(t('Reading recorded activity…','正在讀取已記錄活動…'));
  const data=analysisData,usage=data.totals,coverage=data.coverage;
  const option=(value,label,chosen)=>'<option value="'+escape(value)+'" '+(value===chosen?'selected':'')+'>'+escape(label)+'</option>';
  const filterSelect=(name,label,values)=>'<label class="small">'+label+' <select data-analysis-filter="'+name+'" id="analysis-'+name+'">'+option('all',t('All','全部'),analysisFilters[name])+values.map(value=>option(typeof value==='object'?value.id:value,typeof value==='object'?value.name:name==='activity'?activityLabel(value):value==='unreported'?t('Not reported','未回報'):value,analysisFilters[name])).join('')+'</select></label>';
  const toolbar='<div class="toolbar">'+filterSelect('project',t('Project','專案'),data.dimensions.projects)+filterSelect('activity',t('Activity','活動'),data.dimensions.activity)+filterSelect('tool',t('Tool','工具'),data.dimensions.tool)+filterSelect('model',t('Reported model','回報模型'),data.dimensions.model)+'<label class="small">'+t('Group by','分組')+' <select id="analysis-group" data-analysis-filter="group">'+['activity_kind','tool','model'].map(value=>option(value,{activity_kind:t('Activity','活動'),tool:t('Tool','工具'),model:t('Reported model','回報模型')}[value],analysisFilters.group)).join('')+'</select></label></div>';
  const groups=data.groups.items;
  const groupBody=groups.length?'<div class="panel"><div class="analysis-head"><span>'+t('Recorded group','記錄分組')+'</span><span>'+t('Operations','執行次數')+'</span><span>'+t('Reported time','回報時間')+'</span><span>'+t('Tokens','Tokens')+'</span></div>'+groups.map(group=>'<div class="analysis-row"><strong>'+escape(analysisFilters.group==='activity_kind'?activityLabel(group.id):group.id==='unreported'?t('Not reported','未回報'):group.id)+'</strong><span>'+group.rows+'</span><span>'+escape(group.ms===null?t('Unknown','未知'):(group.time_complete?'':'≥ ')+duration(group.ms)+(group.time_complete?'':' · '+t('partial','不完整')))+'</span><span>'+escape(measuredTokens(group))+'</span></div>').join('')+'</div>':empty(t('No recorded operations match these filters.','沒有符合篩選條件的已記錄執行。'));
  const paging=data.groups.total>30?'<div class="page-nav"><button data-analysis-page="-1" '+(analysisOffset===0?'disabled':'')+'>'+t('Previous','上一頁')+'</button><span>'+Math.floor(analysisOffset/30+1)+' / '+Math.ceil(data.groups.total/30)+'</span><button data-analysis-page="1" '+(data.groups.next_offset===null?'disabled':'')+'>'+t('Next','下一頁')+'</button></div>':'';
  return heading(t('Recorded activity','已記錄活動'),t('Explore measured work by activity, tool and reported model.','依活動、工具與回報模型檢查已量測工作。'))+toolbar+'<div class="panel"><div class="metrics"><div class="metric"><strong>'+escape(measuredTokens(usage||{tokens:null}))+'</strong><span>'+t('Recorded tokens','已記錄 tokens')+'</span></div><div class="metric"><strong>'+escape(duration(usage?.ms))+'</strong><span>'+t('Reported operation time · sum','已回報 operation 時間・加總')+'</span></div><div class="metric"><strong>'+coverage.selected_operations+' / '+coverage.recorded_operations+'</strong><span>'+t('Selected / recorded operations','選取／已記錄執行')+'</span></div></div><div class="detail-body"><p class="small">'+t('Time measurements: ','時間量測：')+coverage.measured_time+' / '+coverage.selected_operations+' · '+t('Complete token reports: ','完整用量回報：')+coverage.measured_tokens+' / '+coverage.selected_operations+'</p><p class="small">'+t('Reported operation time is a sum, not goal elapsed time. Overlapping work and unobserved host conversations remain separate.','回報 operation 時間為加總，不等於目標經過時間。重疊工作與未量測的主機對話另行看待。')+'</p>'+(coverage.unavailable_projects.length||coverage.stale_operations?'<p class="status warning">'+t('Some project or operation records are unavailable or stale.','部分專案或執行記錄無法讀取或已過期。')+'</p>':'')+'</div></div>'+'<div class="toolbar"><label for="analysis-metric">'+t('Compare','比較')+'</label><select id="analysis-metric">'+option('time',t('Recorded time','已記錄時間'),analysisMetric)+option('tokens',t('Recorded tokens','已記錄 tokens'),analysisMetric)+'</select></div>'+renderActivityComparison(groups,{language:lang,metric:analysisMetric})+'<details class="panel detail-body"><summary>'+t('Recorded operation groups','已記錄執行分組')+'</summary>'+groupBody+'</details>'+paging+'<div class="resource-buttons">'+snapshot.projects.map(project=>'<button data-observer="'+escape(project.id)+'">'+escape(project.name)+' · '+t('Complete analysis & history','完整分析與歷史')+' ↗</button>').join('')+'</div>';
}
async function readAnalysis(){if(route().view!=='analysis')return;const scope=JSON.stringify([analysisFilters,analysisOffset]);try{const data=await api('/api/analysis?'+new URLSearchParams({...analysisFilters,limit:30,offset:analysisOffset}));if(route().view==='analysis'&&scope===JSON.stringify([analysisFilters,analysisOffset])){analysisData=data;render();}}catch(error){notice(error.message);}}
async function readCurrentView(){await readControls();if(route().view==='analysis')await readAnalysis();if(route().view==='task'&&tab==='execution')await readExecution();}
